package dev.zomboid.mts;
import java.util.*;
public final class HudTelemetry {
 private static final Map<Object,List<Object>> LABELS=new WeakHashMap<>();
 private static final Map<Object,Long> UPDATED=new WeakHashMap<>();
 public static boolean special(Object vehicle){if(vehicle==null)return false;String k=FamilyWorkshop.kind(vehicle).name();return k.equals("PLANE")||k.equals("HELICOPTER")||k.equals("BOAT");}
 private static Object vehicle(Object gui){return R.get(gui,"vehicle");}
 public static void hudBefore(Object gui){if(!special(vehicle(gui))){Mechanics.hudBefore(gui);return;}Object motor=R.get(R.get(vehicle(gui),"definition"),"motorized");R.set(motor,"halfHUDOnly",false);R.set(motor,"fullHUDOnly",true);R.set(gui,"halfHUDActive",false);R.set(gui,"guiTop",Math.max(0,(int)R.num(R.get(gui,"screenHeight"))-80));}
 public static int width(Object gui,int original){return special(vehicle(gui))?260:Mechanics.width(gui,original);}
 public static int height(Object gui,int original){return special(vehicle(gui))?54:Mechanics.height(gui,original);}
 public static Object texture(Object gui,Object original){return special(vehicle(gui))?"mtsofficialpack:textures/guis/zomboid_telemetry_compact.png":Mechanics.texture(gui,original);}
 public static boolean background(Object gui,boolean original){return special(vehicle(gui))?R.yes(R.get(R.get(R.get(gui,"seat"),"placementDefinition"),"isController")):Mechanics.background(gui,original);}
 public static void hudSetup(Object gui){if(!special(vehicle(gui))){Mechanics.hudSetup(gui);return;}hideNative(gui);int x=(int)R.num(R.get(gui,"guiLeft"))+8,y=(int)R.num(R.get(gui,"guiTop"))+6;Object white=R.get(R.type("minecrafttransportsimulator.baseclasses.ColorRGB"),"WHITE");List<Object> labels=new ArrayList<>();for(int row=0;row<3;row++)labels.add(Mechanics.label(gui,x,y+15*row,"",0.7f,white));LABELS.put(gui,labels);UPDATED.remove(gui);Object bg=R.get(gui,"background");if(bg!=null)R.set(bg,"ignoreGUILightingState",true);}
 private static void hideNative(Object gui){Object health=R.get(gui,"healthLabel");if(health!=null)R.set(health,"visible",false);Object gauges=R.get(gui,"instruments");if(gauges instanceof Iterable<?> it)for(Object gauge:it)R.set(gauge,"visible",false);}
 public static void hudState(Object gui){if(!special(vehicle(gui))){Mechanics.hudState(gui);return;}hideNative(gui);List<Object> labels=LABELS.get(gui);if(labels==null){hudSetup(gui);labels=LABELS.get(gui);}boolean visible=background(gui,true);for(Object label:labels)R.set(label,"visible",visible);if(!visible)return;long now=System.nanoTime();Long last=UPDATED.get(gui);if(last!=null&&now-last<100_000_000L)return;UPDATED.put(gui,now);String[] rows=rows(vehicle(gui));for(int n=0;n<3;n++)R.set(labels.get(n),"text",rows[n]);}
 public static String[] rows(Object vehicle){Object raw=R.get(vehicle,"engines");List<?> engines=raw instanceof Collection<?> c?new ArrayList<>(c):raw instanceof Map<?,?> m?new ArrayList<>(m.values()):List.of();StringBuilder rpms=new StringBuilder("RPM ");double flow=0;int index=0;for(Object engine:engines){if(engine==null)continue;index++;if(index<=4){if(index>1)rpms.append(" | ");if(engines.size()>1)rpms.append(index).append(": ");rpms.append(String.format(Locale.ROOT,"%.0f",safe(R.num(R.get(engine,"rpm")))));}if(R.yes(R.get(engine,"running")))flow+=safe(R.num(R.get(engine,"fuelFlow")));}if(index==0)rpms.append("0");if(index>4)rpms.append(" +").append(index-4);double speed=safe(Math.abs(R.num(R.get(vehicle,"velocity"))))*72;Object tank=R.get(vehicle,"fuelTank");double level=tank==null?0:safe(R.num(R.call(tank,"getFluidLevel"))),capacity=tank==null?0:safe(R.num(R.call(tank,"getMaxLevel")));double percent=capacity>0?Math.min(100,level/capacity*100):0;String fuel=WorkshopLanguage.text("Combustible"),consumption=WorkshopLanguage.text("Consumo");return new String[]{String.format(Locale.ROOT,"%.0f km/h | %s",speed,rpms),String.format(Locale.ROOT,"%s %.0f%% | %.1f / %.1f L",fuel,percent,level/1000,capacity/1000),String.format(Locale.ROOT,"%s %.2f L/min",consumption,flow*20*60/1000)};}
 private static double safe(double v){return Double.isFinite(v)?Math.max(0,v):0;}
}
